import * as m from '@opencode/schema/event-manifest'

function fieldNames(ast) {
  if (!ast) return []
  // Struct AST
  if (Array.isArray(ast.propertySignatures)) {
    return ast.propertySignatures.map((p) => String(p.name))
  }
  // Union / Suspend / Ref
  if (ast.from) return fieldNames(ast.from)
  if (ast.to) return fieldNames(ast.to)
  return []
}

function walk(def, depth=0) {
  const t = def && def.type
  if (!t) return
  // find data schema
  let data = def.data
  let names = fieldNames(data && data.ast)
  console.log(t, '=>', names.join(', '))
}

const all = m.Definitions
for (const d of all) walk(d)
