78: func classifyOpenCodeExportError(ctx context.Context, err error, stderr, sessionID string) error {
79: 	if errors.Is(ctx.Err(), context.Canceled) {
80: 		return context.Canceled
81: 	}
82: 	if errors.Is(ctx.Err(), context.DeadlineExceeded) {
83: 		return &openCodeExportError{
84: 			message: fmt.Sprintf("OpenCode export timed out after %s. Try again.", openCodeCommandTimeout),
85: 			cause:   context.DeadlineExceeded,
86: 		}
87: 	}
88: 
89: 	var execErr *exec.Error
90: 	if errors.As(err, &execErr) && errors.Is(execErr.Err, exec.ErrNotFound) {
91: 		return &openCodeExportError{
92: 			message: "OpenCode is not installed or is not available in PATH.",
93: 			cause:   err,
94: 		}
95: 	}
96: 	if errors.Is(err, os.ErrPermission) {
97: 		return &openCodeExportError{
98: 			message: "OpenCode could not be started because of insufficient permissions.",
99: 			cause:   err,
100: 		}
101: 	}
102: 
103: 	var exitErr *exec.ExitError
104: 	if errors.As(err, &exitErr) {
105: 		detail := formatOpenCodeErrorDetail(stderr)
106: 		if strings.HasPrefix(strings.ToLower(detail), "session not found") {
107: 			return &openCodeExportError{
108: 				message: fmt.Sprintf("OpenCode session %q was not found. Check the session ID and try again.", sessionID),
109: 				cause:   err,
110: 			}
111: 		}
112: 		if detail != "" {
113: 			return &openCodeExportError{
114: 				message: fmt.Sprintf("OpenCode could not export session %q: %s", sessionID, detail),
115: 				cause:   err,
116: 			}
117: 		}
118: 		return &openCodeExportError{
119: 			message: fmt.Sprintf("OpenCode could not export session %q.", sessionID),
120: 			cause:   err,
121: 		}
122: 	}
123: 
124: 	return &openCodeExportError{message: "OpenCode export could not be started.", cause: err}
125: }
