127: func formatOpenCodeErrorDetail(stderr string) string {
128: 	for _, rawLine := range strings.Split(stderr, "\n") {
129: 		line := strings.Map(func(r rune) rune {
130: 			if unicode.IsControl(r) {
131: 				return -1
132: 			}
133: 			return r
134: 		}, ansi.Strip(rawLine))
135: 		line = strings.TrimSpace(line)
136: 		if len(line) < len("error:") || !strings.EqualFold(line[:len("error:")], "error:") {
137: 			continue
138: 		}
139: 
140: 		detail := strings.Join(strings.Fields(redact.String(line[len("error:"):])), " ")
141: 		runes := []rune(detail)
142: 		if len(runes) > openCodeErrorDetailMaxRunes {
143: 			return string(runes[:openCodeErrorDetailMaxRunes]) + "…"
144: 		}
145: 		return detail
146: 	}
147: 	return ""
148: }
