63: // compactOpenCode converts a full OpenCode session JSON into transcript lines.
64: // opts.StartLine is treated as a message-index offset (not a newline offset)
65: // because the OpenCode transcript is a single JSON object.
66: func compactOpenCode(content []byte, opts MetadataFields) ([]byte, error) {
67: 	var session struct {
68: 		Messages []openCodeMessage `json:"messages"`
69: 	}
70: 	if err := json.Unmarshal(bytes.TrimSpace(content), &session); err != nil {
71: 		return nil, fmt.Errorf("parsing opencode session: %w", err)
72: 	}
73: 
74: 	messages := session.Messages
75: 	if opts.StartLine > 0 {
76: 		if opts.StartLine >= len(messages) {
77: 			return []byte{}, nil
78: 		}
79: 		messages = messages[opts.StartLine:]
80: 	}
81: 
82: 	base := newTranscriptLine(opts)
83: 	var result []byte
84: 
85: 	for _, msg := range messages {
86: 		ts := msToTimestamp(msg.Info.Time.Created)
