161: 			}
162: 			if stateRaw := part["state"]; stateRaw != nil {
163: 				var state map[string]json.RawMessage
164: 				if json.Unmarshal(stateRaw, &state) == nil {
165: 					if inp := state["input"]; inp != nil {
