169: 				}
170: 			}
171: 			content = append(content, toolBlock)
172: 		}
173: 	}
174: 
175: 	contentJSON, err := json.Marshal(content)
176: 	if err != nil {
177: 		return
178: 	}
179: 
180: 	line := base
181: 	line.Type = transcript.TypeAssistant
182: 	line.TS = ts
183: 	line.ID = msg.Info.ID
184: 	line.Content = contentJSON
